  const [preferences,setPreferences]=useState(()=>{try{return JSON.parse(localStorage.getItem('da_user_preferences')||'{}')}catch{return {}}})
  const t=I18N[locale]||I18N.en
  useEffect(()=>{localStorage.setItem('da_locale',locale);const option=LANGUAGE_OPTIONS.find(([id])=>id===locale);document.documentElement.lang=option?.[3]||'en-US';document.title=t.seoTitle||`Document Automation AI · ${t.lang}`;document.querySelector('meta[name=description]')?.setAttribute('content',t.heroDesc)},[locale,t.lang,t.seoTitle,t.heroDesc])
  useEffect(()=>{if(!authToken){setCurrentUser(null);return}let cancelled=false;fetch(`${API_BASE}/api/auth/me`,{headers:{Authorization:`Bearer ${authToken}`}}).then(async r=>{const j=await readJson(r);if(r.status===401||r.status===403){localStorage.removeItem('da_auth_token');if(!cancelled){setAuthToken('');setCurrentUser(null)};return}if(!r.ok)throw new Error(j.detail||'Session check failed');if(!cancelled)setCurrentUser(j.user)}).catch(()=>{/* Temporary network/backend errors must not destroy a valid local session. */});return()=>{cancelled=true}},[authToken])
  useEffect(()=>{if(!currentUser)return;setForm(v=>({...v,name:currentUser.name||v.name||'',email:currentUser.email||v.email||'',company:''}))},[currentUser])
