  useEffect(()=>{if(page!=='order')return;const p=preferences||{};if(p.targetLanguage)setTranslationTargets([p.targetLanguage]);if(p.outputFormat&&p.outputFormat!=='original'){setServices(v=>[...new Set([...v,'conversion'])]);setOutputFormats([p.outputFormat])}const bilingual=p.bilingualLayout!=='target-only';setOutputOptions(v=>({...v,preserve_layout:true,bilingual_layout:p.bilingualLayout||'auto',ocr_mode:p.ocrMode||'standard',translation_style:p.translationStyle||'technical',knowledge_base:p.knowledgeBase||'none',page_size:p.pageSize||'A4',quality_mode:p.qualityMode||'balanced',auto_quality:p.autoQuality!==false,auto_correct:p.autoCorrect!==false,bilingual}))},[page,preferences])
