function TeamPermissionsCenter({setPage,currentUser}){
 const isZh=document.documentElement.lang.startsWith('zh')
 const [members,setMembers]=useState(()=>{try{return JSON.parse(localStorage.getItem('da_team_members')||'[]')}catch{return []}})
 const [email,setEmail]=useState(''),[message,setMessage]=useState('')
 const owner={name:currentUser?.name||currentUser?.email||'Owner',email:currentUser?.email||'',role:isZh?'管理员':'Administrator',status:isZh?'已启用':'Active'}
 const invite=()=>{const v=email.trim();if(!v)return;const next=[...members,{id:Date.now(),name:v.split('@')[0],email:v,role:isZh?'成员':'Member',status:isZh?'待接受':'Pending'}];setMembers(next);localStorage.setItem('da_team_members',JSON.stringify(next));setEmail('');setMessage(isZh?'邀请已保存。':'Invitation saved.')}
 const remove=id=>{const next=members.filter(x=>x.id!==id);setMembers(next);localStorage.setItem('da_team_members',JSON.stringify(next))}
 return <main className="team-center-v335"><EnterpriseSidebar setPage={setPage} active="team"/><section className="team-center-content"><header><div><span>{isZh?'企业协作中心':'ENTERPRISE COLLABORATION'}</span><h1>{isZh?'团队与权限':'Team & Permissions'}</h1><p>{isZh?'管理成员、角色和工作区访问权限。':'Manage members, roles and workspace access.'}</p></div></header><section className="team-metrics"><article><small>{isZh?'成员总数':'Members'}</small><b>{members.length+1}</b></article><article><small>{isZh?'管理员':'Administrators'}</small><b>1</b></article><article><small>{isZh?'待接受邀请':'Pending invites'}</small><b>{members.filter(x=>String(x.status).includes(isZh?'待':'Pending')).length}</b></article></section><section className="team-card"><header><h2>{isZh?'邀请成员':'Invite member'}</h2><div><input value={email} onChange={e=>setEmail(e.target.value)} placeholder={isZh?'输入成员邮箱':'Member email'}/><button onClick={invite}>{isZh?'发送邀请':'Send invite'}</button></div></header>{message&&<p className="team-message">{message}</p>}<div className="team-table"><div className="team-row team-head"><span>{isZh?'成员':'Member'}</span><span>{isZh?'角色':'Role'}</span><span>{isZh?'状态':'Status'}</span><span>{isZh?'操作':'Action'}</span></div>{[owner,...members].map((m,i)=><div className="team-row" key={m.id||'owner'}><span><b>{m.name}</b><small>{m.email}</small></span><span>{m.role}</span><span>{m.status}</span><span>{i===0?'—':<button onClick={()=>remove(m.id)}>{isZh?'移除':'Remove'}</button>}</span></div>)}</div></section></section></main>
}

function TranslationSettings({t}){
 const isZh=document.documentElement.lang.startsWith('zh')
 const fallbackProviders=[
  {id:'deepseek',label:'DeepSeek',models:['deepseek-chat','deepseek-reasoner','deepseek-v4-flash','deepseek-v4-pro'],model:'deepseek-chat',base_url:'https://api.deepseek.com/v1'},
  {id:'openai',label:'OpenAI',models:['gpt-4.1-mini','gpt-4.1','gpt-4o-mini'],model:'gpt-4.1-mini',base_url:'https://api.openai.com/v1'},
  {id:'gemini',label:'Google Gemini',models:['gemini-2.5-flash','gemini-2.5-pro'],model:'gemini-2.5-flash',base_url:'https://generativelanguage.googleapis.com/v1beta'},
  {id:'claude',label:'Anthropic Claude',models:['claude-3-5-haiku-latest','claude-sonnet-4-20250514'],model:'claude-3-5-haiku-latest',base_url:'https://api.anthropic.com/v1'},
  {id:'openrouter',label:'OpenRouter',models:['openai/gpt-4.1-mini','deepseek/deepseek-chat-v3-0324','google/gemini-2.5-flash','anthropic/claude-3.5-haiku'],model:'openai/gpt-4.1-mini',base_url:'https://openrouter.ai/api/v1'}
 ]
 const [form,setForm]=useState({provider:'deepseek',api_key:'',model:'deepseek-chat',base_url:'https://api.deepseek.com/v1'}),[providers,setProviders]=useState(fallbackProviders),[profiles,setProfiles]=useState({}),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[showKey,setShowKey]=useState(false),[tests,setTests]=useState({})
 const call=async(path,method='GET',body)=>{const r=await fetch(`${API_BASE}${path}`,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw new Error(j.detail||t.settingsFailed);return j}
 const load=()=>call('/api/admin/translation-settings').then(j=>{const list=j.providers?.length?j.providers:fallbackProviders;setProviders(list);setProfiles(j.profiles||{});const p=j.provider&&j.provider!=='none'?j.provider:'deepseek',meta=list.find(x=>x.id===p)||list[0],profile=j.profiles?.[p]||{};setForm(v=>({...v,provider:p,api_key:'',model:profile.model||j.model||meta.model,base_url:profile.base_url||j.base_url||meta.base_url}))}).catch(e=>setMessage(e.message))
 useEffect(load,[])
 const chooseProvider=p=>{const meta=providers.find(x=>x.id===p)||fallbackProviders.find(x=>x.id===p),profile=profiles[p]||{};setMessage('');setShowKey(false);setForm(v=>({...v,provider:p,api_key:'',model:profile.model||meta?.model||'',base_url:profile.base_url||meta?.base_url||''}))}
 const save=async()=>{setBusy(true);setMessage('');try{const j=await call('/api/admin/translation-settings','PUT',{provider:form.provider,api_key:form.api_key,model:form.model,base_url:form.base_url});setProfiles(j.settings?.profiles||profiles);setForm(v=>({...v,api_key:''}));setMessage(isZh?'已保存，并设为默认 Provider。':'Saved and set as default provider.')}catch(e){setMessage(e.message)}finally{setBusy(false)}}
 const test=async()=>{setBusy(true);setMessage('');const testedAt=new Date();try{const saved=await call('/api/admin/translation-settings','PUT',{provider:form.provider,api_key:form.api_key,model:form.model,base_url:form.base_url});setProfiles(saved.settings?.profiles||profiles);const j=await call('/api/admin/translation-settings/test','POST');setTests(v=>({...v,[form.provider]:{ok:true,elapsed_ms:j.elapsed_ms,model:j.model,tested_at:testedAt.toISOString(),detail:j.translated_text||''}}));setForm(v=>({...v,api_key:''}));setMessage(isZh?`连接成功：${j.provider} / ${j.model}，延迟 ${j.elapsed_ms} ms，测试译文：${j.translated_text}`:`Connected: ${j.provider} / ${j.model}, ${j.elapsed_ms} ms. Result: ${j.translated_text}`)}catch(e){setTests(v=>({...v,[form.provider]:{ok:false,tested_at:testedAt.toISOString(),detail:e.message}}));setMessage(isZh?`连接失败：${e.message}`:`Connection failed: ${e.message}`)}finally{setBusy(false)}}
 const current=providers.find(x=>x.id===form.provider)||fallbackProviders[0],configured=Boolean(profiles?.[form.provider]?.configured),testInfo=tests[form.provider]
 return <article className="translation-settings provider-center"><div className="provider-center-head"><div><span>AI PROVIDER CENTER</span><h2>{isZh?'AI 服务商中心':'AI Provider Center'}</h2><p>{isZh?'统一管理 AI 服务商、模型、连接状态和默认调用配置。':'Manage providers, models, connection status and the default AI service.'}</p></div><div className={`provider-overall ${configured?'connected':'disconnected'}`}><i/>{configured?(isZh?'已配置':'Configured'):(isZh?'未配置':'Not configured')}</div></div><div className="provider-tabs">{providers.map(p=>{const selected=form.provider===p.id,ready=Boolean(profiles?.[p.id]?.configured);return <button type="button" key={p.id} className={selected?'active':''} onClick={()=>chooseProvider(p.id)}><span>{p.label}{selected&&<em>{isZh?'默认':'Default'}</em>}</span><small className={ready?'connected':'disconnected'}>{ready?(isZh?'已连接':'Connected'):(isZh?'未连接':'Not connected')}</small></button>})}</div><section className="provider-status-grid"><article><span>{isZh?'当前 Provider':'Current provider'}</span><b>{current?.label}</b></article><article><span>{isZh?'当前模型':'Current model'}</span><b>{form.model||'—'}</b></article><article><span>{isZh?'连接状态':'Connection'}</span><b>{configured?(isZh?'已连接':'Connected'):(isZh?'未连接':'Not connected')}</b></article><article><span>{isZh?'最近延迟':'Latency'}</span><b>{testInfo?.elapsed_ms!=null?`${testInfo.elapsed_ms} ms`:'—'}</b></article><article><span>{isZh?'最后测试时间':'Last tested'}</span><b>{testInfo?.tested_at?new Date(testInfo.tested_at).toLocaleString():(isZh?'尚未测试':'Not tested')}</b></article></section><div className="settings-grid provider-settings-grid"><label>{t.apiKey}<span className="secret-input"><input type={showKey?'text':'password'} value={form.api_key} onChange={e=>setForm({...form,api_key:e.target.value})} placeholder={configured?(isZh?'已保存；留空保持不变':'Saved; leave blank to keep'):''}/><button type="button" onClick={()=>setShowKey(v=>!v)} title={showKey?(isZh?'隐藏':'Hide'):(isZh?'显示':'Show')}>{showKey?<EyeOff/>:<Eye/>}</button></span></label><label>{t.model}<select value={form.model} onChange={e=>setForm({...form,model:e.target.value})}>{(current?.models||[current?.model]).filter(Boolean).map(m=><option value={m} key={m}>{m}</option>)}</select></label></div><div className="settings-actions"><button onClick={save} disabled={busy}>{isZh?'保存并设为默认':'Save as default'}</button><button className="secondary-provider-action" onClick={test} disabled={busy}>{busy?(isZh?'测试中…':'Testing…'):t.testConnection}</button></div>{message&&<p className={`settings-message ${testInfo&&!testInfo.ok?'error':''}`}>{message}</p>}<div className="v302-provider-roadmap"><b>{isZh?'V30.2 企业路由已启用':'V30.2 enterprise routing enabled'}</b><span>{isZh?'支持主/备用 Provider、自动故障切换、按处理阶段分配 Provider、调用统计与团队权限接口。':'Primary/backup providers, automatic failover, stage routing, usage statistics and team permission APIs are available.'}</span></div></article>
}

function ProjectCenter({locale,setPage,authToken}){
 const isZh=locale==='zh', headers={Authorization:`Bearer ${authToken}`}
 const [data,setData]=useState({summary:{},projects:[]}),[loading,setLoading]=useState(true),[error,setError]=useState('')
 const [query,setQuery]=useState(''),[status,setStatus]=useState('all'),[priority,setPriority]=useState('all'),[sort,setSort]=useState('updated_desc'),[selected,setSelected]=useState(null),[activity,setActivity]=useState([]),[edit,setEdit]=useState(null)
 const [archived,setArchived]=useState(false),[view,setView]=useState('grid'),[density,setDensity]=useState('comfortable'),[checked,setChecked]=useState([]),[menu,setMenu]=useState(null),[confirm,setConfirm]=useState(null)
 const load=async()=>{if(!authToken)return;setLoading(true);try{const p=new URLSearchParams({q:query,status,archived:String(archived)});const r=await fetch(`${API_BASE}/api/projects?${p}`,{headers});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Failed');setData(j);setChecked(v=>v.filter(id=>j.projects.some(p=>p.id===id)));setError('')}catch(e){setError(e.message)}finally{setLoading(false)}}
 useEffect(()=>{const id=setTimeout(load,180);return()=>clearTimeout(id)},[query,status,archived,authToken])
 const openProject=async(p)=>{try{const r=await fetch(`${API_BASE}/api/projects/${p.id}`,{headers});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Failed');setSelected(j.project);setActivity(j.activity||[])}catch(e){setError(e.message)}}
 const save=async(patch,target=selected||edit)=>{if(!target)return;const r=await fetch(`${API_BASE}/api/projects/${target.id}`,{method:'PATCH',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(patch)});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Save failed');if(selected?.id===target.id)setSelected(j.project);setEdit(null);await load()}
 const action=async(ids,operation)=>{const r=await fetch(`${API_BASE}/api/projects/batch-action`,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({ids,operation})});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Action failed');setChecked([]);setMenu(null);setConfirm(null);if(selected&&ids.includes(selected.id))setSelected(null);await load()}
 const statusLabel=p=>({processing:isZh?'处理中':'Processing',completed:isZh?'已完成':'Completed',failed:isZh?'失败':'Failed',pending:isZh?'等待中':'Pending'}[p.status_kind]||p.status)
 const priorityLabel=p=>({normal:isZh?'普通':'Normal',high:isZh?'高':'High',urgent:isZh?'紧急':'Urgent'}[p]||p)
 const visible=useMemo(()=>data.projects.filter(p=>priority==='all'||p.priority===priority).sort((a,b)=>{if(sort==='created_desc')return new Date(b.created_at)-new Date(a.created_at);if(sort==='name')return a.title.localeCompare(b.title);if(sort==='priority')return({urgent:0,high:1,normal:2}[a.priority]??3)-({urgent:0,high:1,normal:2}[b.priority]??3);return new Date(b.updated_at)-new Date(a.updated_at)}),[data.projects,priority,sort])
 const stepLabel=key=>({validate:isZh?'源文件校验':'Validation',analyze:isZh?'结构分析':'Analysis',ocr:'OCR',translation:isZh?'AI 翻译':'AI translation',conversion:isZh?'格式转换':'Conversion',layout:isZh?'版式重建':'Layout',quality:isZh?'质量检查':'Quality check',export:isZh?'生成交付文件':'Delivery',completed:isZh?'已完成':'Completed'}[key]||key||'-')
 const toggle=id=>setChecked(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id])
 const sortedJobs=[...(data.jobs||[])].filter(x=>{const q=query.trim().toLowerCase();if(!q)return true;return [x.order_number,x.files?.[0]?.original_name,x.id,x.processor_name].filter(Boolean).some(v=>String(v).toLowerCase().includes(q))}).sort((a,b)=>{const av=new Date(a.updated_at||a.created_at||0).getTime(),bv=new Date(b.updated_at||b.created_at||0).getTime();if(sort==='oldest')return av-bv;if(sort==='status')return String(a.status||'').localeCompare(String(b.status||''));return bv-av})
 const completedIds=(data.jobs||[]).filter(x=>['completed','partial_completed'].includes(x.status)||['completed','partial_completed'].includes(x.job?.state)).map(x=>x.id)
 if(!authToken)return <main className="project-page"><section className="processing-auth"><FolderOpen/><h1>{isZh?'请先登录':'Sign in required'}</h1><button onClick={()=>setPage('login')}>{isZh?'前往登录':'Sign in'}</button></section></main>
 if(selected)return <div className="enterprise-page-layout document-center-layout"><EnterpriseSidebar setPage={setPage} active="projects"/><main className="project-page enterprise-page-content"><section className="project-shell"><button className="back-link" onClick={()=>setSelected(null)}><ArrowLeft/>{isZh?'返回项目列表':'Back to projects'}</button><div className="project-detail-head"><div><span>{selected.project_number}</span><h1>{selected.title}</h1><p>{selected.order_number} · {selected.owner}</p></div><div className="project-head-actions"><button onClick={()=>setEdit(selected)}><Edit3/>{isZh?'编辑':'Edit'}</button><button onClick={()=>save({favorite:!selected.favorite})}><Star/>{selected.favorite?(isZh?'取消收藏':'Unfavorite'):(isZh?'收藏':'Favorite')}</button><button onClick={()=>action([selected.id],selected.archived?'restore':'archive')}>{selected.archived?<ArchiveRestore/>:<Archive/>}{selected.archived?(isZh?'恢复':'Restore'):(isZh?'归档':'Archive')}</button><button className="danger-outline" onClick={()=>setConfirm({ids:[selected.id],operation:'delete',title:selected.title})}><Trash2/>{isZh?'删除':'Delete'}</button></div></div><section className="project-detail-grid"><div className="project-primary"><div className={`project-progress-card ${selected.status_kind}`}><div><b>{statusLabel(selected)}</b><strong>{selected.status_kind==='completed'?'✓':`${selected.progress}%`}</strong></div>{selected.status_kind==='completed'?<div className="project-complete-note"><CircleCheck/>{isZh?'项目已完成，可下载交付文件。':'Project completed. Deliverables are ready.'}</div>:<><i><em style={{width:`${selected.progress}%`}}/></i><small>{isZh?'当前阶段：':'Current stage: '}{stepLabel(selected.current_step)}</small></>}</div><article className="project-files"><h2>{isZh?'项目文件':'Project files'} <small>({selected.files.length})</small></h2>{selected.files.map((f,i)=><div className="project-file-row" key={f.id||i}><FileText/><div><b>{f.original_name}</b><small>{Math.max(1,Math.round((f.size_bytes||0)/1024))} KB · {stepLabel(selected.current_step)}</small></div><span className={`project-status ${selected.status_kind}`}>{statusLabel(selected)}</span></div>)}</article><article className="project-timeline"><h2>{isZh?'处理时间轴与活动日志':'Timeline & activity log'}</h2>{[...(selected.events||[]),...activity].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,30).map((e,i)=><div key={i}><Clock3/><span>{new Date(e.created_at).toLocaleString()}</span><b>{stepLabel(e.step||e.action)}</b><p>{e.message}</p></div>)}</article></div><aside className="project-sidebar"><article><h3>{isZh?'项目统计':'Project statistics'}</h3><p><span>{isZh?'文件':'Files'}</span><b>{selected.file_count}</b></p><p><span>{isZh?'AI 点数':'AI credits'}</span><b>{selected.credits_used}</b></p><p><span>{isZh?'优先级':'Priority'}</span><b>{priorityLabel(selected.priority)}</b></p><p><span>{isZh?'负责人':'Owner'}</span><b>{selected.owner}</b></p></article><article><h3>{isZh?'交付文件':'Delivery files'}</h3>{selected.outputs?.length?selected.outputs.map(f=><a key={f.id} href={`${API_BASE}${f.download_url}`}><Download/>{f.original_name}</a>):<small>{isZh?'尚未生成交付文件':'No delivery files yet'}</small>}</article></aside></section>{edit&&<div className="project-modal"><form onSubmit={e=>{e.preventDefault();save({title:edit.title,owner:edit.owner,priority:edit.priority,notes:edit.notes},edit)}}><h2>{isZh?'编辑项目':'Edit project'}</h2><label>{isZh?'项目名称':'Project name'}<input value={edit.title} onChange={e=>setEdit({...edit,title:e.target.value})}/></label><label>{isZh?'负责人':'Owner'}<input value={edit.owner} onChange={e=>setEdit({...edit,owner:e.target.value})}/></label><label>{isZh?'优先级':'Priority'}<select value={edit.priority} onChange={e=>setEdit({...edit,priority:e.target.value})}><option value="normal">{isZh?'普通':'Normal'}</option><option value="high">{isZh?'高':'High'}</option><option value="urgent">{isZh?'紧急':'Urgent'}</option></select></label><label>{isZh?'备注':'Notes'}<textarea value={edit.notes} onChange={e=>setEdit({...edit,notes:e.target.value})}/></label><div><button type="button" onClick={()=>setEdit(null)}>{isZh?'取消':'Cancel'}</button><button>{isZh?'保存':'Save'}</button></div></form></div>}{confirm&&<ConfirmDialog {...{confirm,setConfirm,action,isZh}}/>}</section></main></div>
 return <div className="enterprise-page-layout document-center-layout"><EnterpriseSidebar setPage={setPage} active="projects"/><main className="project-page enterprise-page-content"><section className="project-shell"><div className="project-title"><div><span>V{VERSION} · ENTERPRISE PROJECT CENTER</span><h1>{isZh?'企业项目中心':'Enterprise Project Center'}</h1><p>{isZh?'搜索、筛选、归档和批量管理所有企业项目。':'Search, filter, archive and manage enterprise projects in bulk.'}</p></div><button className="new-project-btn" onClick={()=>setPage('order')}><Sparkles/>{isZh?'新建项目':'New project'}</button></div><section className="project-metrics"><article><span>{isZh?'项目总数':'Projects'}</span><b>{data.summary.total||0}</b></article><article><span>{isZh?'处理中':'Processing'}</span><b>{data.summary.processing||0}</b></article><article><span>{isZh?'已完成':'Completed'}</span><b>{data.summary.completed||0}</b></article><article><span>{isZh?'失败':'Failed'}</span><b>{data.summary.failed||0}</b></article><article><span>{isZh?'文件总数':'Files'}</span><b>{data.summary.files||0}</b></article></section><div className="project-search-row"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={isZh?'搜索项目名称、编号、订单号或标签':'Search name, project ID, order or tag'}/><span>{visible.length} {isZh?'个项目':'projects'}</span></div><div className="project-filter-row"><div className="status-tabs">{[['all',isZh?'全部':'All'],['processing',isZh?'处理中':'Processing'],['completed',isZh?'已完成':'Completed'],['failed',isZh?'失败':'Failed']].map(([v,l])=><button className={!archived&&status===v?'active':''} onClick={()=>{setArchived(false);setStatus(v)}} key={v}>{l}</button>)}<button className={archived?'active':''} onClick={()=>setArchived(true)}>{isZh?'归档':'Archived'}</button></div><select value={priority} onChange={e=>setPriority(e.target.value)}><option value="all">{isZh?'全部优先级':'All priorities'}</option><option value="urgent">{isZh?'紧急':'Urgent'}</option><option value="high">{isZh?'高':'High'}</option><option value="normal">{isZh?'普通':'Normal'}</option></select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="updated_desc">{isZh?'最近更新':'Recently updated'}</option><option value="created_desc">{isZh?'最近创建':'Recently created'}</option><option value="priority">{isZh?'按优先级':'Priority'}</option><option value="name">{isZh?'按名称':'Name'}</option></select><button className="icon-text-btn" onClick={load}><RefreshCw/>{isZh?'刷新':'Refresh'}</button></div>{checked.length>0&&<div className="bulk-bar"><b>{isZh?`已选择 ${checked.length} 项`:`${checked.length} selected`}</b><button onClick={()=>action(checked,archived?'restore':'archive')}>{archived?<ArchiveRestore/>:<Archive/>}{archived?(isZh?'恢复':'Restore'):(isZh?'归档':'Archive')}</button><button className="danger-outline" onClick={()=>setConfirm({ids:checked,operation:'delete',title:isZh?`${checked.length} 个项目`:`${checked.length} projects`})}><Trash2/>{isZh?'删除':'Delete'}</button><button onClick={()=>setChecked([])}>{isZh?'取消选择':'Clear'}</button></div>}{error&&<div className="processing-error">{error}</div>}{loading?<div className="processing-empty">{isZh?'正在加载项目…':'Loading projects…'}</div>:<section className="project-list grid comfortable">{visible.map(p=><article className={`project-card ${p.status_kind}`} key={p.id}><button className="select-project" onClick={e=>{e.stopPropagation();toggle(p.id)}}>{checked.includes(p.id)?<CheckSquare/>:<Square/>}</button><button className="project-card-main" onClick={()=>openProject(p)}><div className="project-card-head"><div><small>{p.project_number}</small><h3>{p.title}</h3><p>{p.order_number} · {p.owner}</p></div><span className={`project-status ${p.status_kind}`}>{statusLabel(p)}</span></div><div className="project-card-meta"><span>{p.file_count} {isZh?'个文件':'files'}</span><span>{priorityLabel(p.priority)}</span><span>{stepLabel(p.current_step)}</span><span>{p.credits_used} {isZh?'点':'credits'}</span></div>{p.status_kind==='completed'?<div className="project-delivered"><CircleCheck/>{isZh?'交付已就绪':'Delivery ready'}</div>:<div className="project-card-progress"><i><em style={{width:`${p.progress}%`}}/></i><b>{p.progress}%</b></div>}</button><div className="project-menu-wrap"><button onClick={()=>setMenu(menu===p.id?null:p.id)}><MoreHorizontal/></button>{menu===p.id&&<div className="project-action-menu"><button onClick={()=>openProject(p)}>{isZh?'查看详情':'View details'}</button><button onClick={()=>save({favorite:!p.favorite},p)}><Star/>{p.favorite?(isZh?'取消收藏':'Unfavorite'):(isZh?'收藏':'Favorite')}</button><button onClick={()=>action([p.id],p.archived?'restore':'archive')}>{p.archived?<ArchiveRestore/>:<Archive/>}{p.archived?(isZh?'恢复':'Restore'):(isZh?'归档':'Archive')}</button>{p.status_kind==='failed'&&<button onClick={()=>action([p.id],'retry')}><RotateCcw/>{isZh?'重新处理':'Retry'}</button>}<button className="danger" onClick={()=>setConfirm({ids:[p.id],operation:'delete',title:p.title})}><Trash2/>{isZh?'删除':'Delete'}</button></div>}</div></article>)}</section>}{!loading&&!visible.length&&<div className="processing-empty"><FolderOpen/><h2>{archived?(isZh?'暂无归档项目':'No archived projects'):(isZh?'没有匹配的项目':'No matching projects')}</h2></div>}{confirm&&<ConfirmDialog {...{confirm,setConfirm,action,isZh}}/>}</section></main></div>
}

function ConfirmDialog({confirm,setConfirm,action,isZh}){
 const retry=confirm.operation==='retry'
 return <div className="project-modal confirm-modal"><div className="confirm-card"><AlertTriangle/><h2>{retry?(isZh?'确认重新处理？':'Confirm reprocessing?'):(isZh?'确认删除？':'Confirm deletion?')}</h2><p>{confirm.title}</p><small>{retry?(isZh?'确认后将创建一个新的处理任务并进入队列；原处理记录、日志和交付文件全部保留。':'A new processing job will be queued. The original processing record, logs and delivery files will be retained.'):confirm.permanent?(isZh?'将永久删除处理记录、日志和交付文件，此操作不可恢复。':'Processing records, logs and delivery files will be permanently deleted. This cannot be undone.'):(isZh?'项目将进入回收站，处理记录、交付文件和日志不会立即永久删除。':'The project will move to the recycle bin. Records and files are not permanently removed immediately.')}</small><div><button onClick={()=>setConfirm(null)}>{isZh?'取消':'Cancel'}</button><button className={retry?'confirm-retry-button':'danger-button'} onClick={()=>action(confirm.ids,confirm.operation)}>{retry?(isZh?'确认重新处理':'Confirm reprocessing'):confirm.permanent?(isZh?'永久删除':'Delete permanently'):(isZh?'移到回收站':'Move to recycle bin')}</button></div></div></div>
}

function ProcessingCenter({t,setPage,authToken}){
 const isZh=document.documentElement.lang.startsWith('zh'),headers={Authorization:`Bearer ${authToken}`}
 const [data,setData]=useState({summary:{},jobs:[]}),[loading,setLoading]=useState(true),[error,setError]=useState(''),[expanded,setExpanded]=useState(null),[filter,setFilter]=useState('active'),[checked,setChecked]=useState([]),[confirm,setConfirm]=useState(null),[sort,setSort]=useState('newest'),[query,setQuery]=useState('')
 const load=async()=>{if(!authToken)return;setLoading(true);try{const r=await fetch(`${API_BASE}/api/processing-center/jobs?view=all`,{headers});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Failed');setData(j);setChecked(v=>v.filter(id=>j.jobs.some(x=>x.id===id)));setError('')}catch(e){setError(e.message)}finally{setLoading(false)}}
 useEffect(()=>{load();const timer=setInterval(()=>{if(filter==='active')load()},5000);return()=>clearInterval(timer)},[authToken,filter])
 const controlJob=async(jobId,operation)=>{try{const r=await fetch(`${API_BASE}/api/processing-center/jobs/${jobId}/${operation}`,{method:'POST',headers});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Operation failed');await load()}catch(e){setError(e.message)}}
 const taskAction=async(ids,operation)=>{try{if(operation==='retry'){for(const id of ids){const r=await fetch(`${API_BASE}/api/processing-center/orders/${id}/retry`,{method:'POST',headers});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Retry failed')}}else{const apiOperation=operation==='delete'?'purge':operation;const r=await fetch(`${API_BASE}/api/projects/batch-action`,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({ids,operation:apiOperation})});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Action failed')}setChecked([]);setConfirm(null);await load()}catch(e){setError(e.message)}}
 const statusText=s=>({queued:isZh?'排队中':'Queued',processing:isZh?'处理中':'Processing',paused:isZh?'已暂停':'Paused',cancelling:isZh?'正在停止':'Stopping',cancelled:isZh?'已停止':'Stopped',quality_review:isZh?'质量复核':'Quality review',partial_completed:isZh?'部分完成':'Partially completed',completed:isZh?'已完成':'Completed',failed:isZh?'失败':'Failed'}[s]||s||'-')
 const stepText=k=>({validate:isZh?'源文件校验':'Validate files',analyze:isZh?'文档结构分析':'Analyze structure',ocr:'OCR',translation:isZh?'AI 翻译':'AI translation',conversion:isZh?'格式转换':'Format conversion',layout:isZh?'版式重建':'Layout reconstruction',quality:isZh?'质量检查':'Quality check',export:isZh?'生成交付文件':'Generate delivery',completed:isZh?'已完成':'Completed'}[k]||k)
 const liveState=x=>String(x.job?.state||x.status||'').toLowerCase()
 const stateGroup=x=>{const state=liveState(x);if(['completed','partial_completed','quality_review'].includes(state))return 'completed';if(['failed','cancelled'].includes(state))return 'failed';return 'active'}
 const liveSummary=useMemo(()=>{const jobs=data.jobs||[];return {total:jobs.length,active:jobs.filter(x=>stateGroup(x)==='active').length,completed:jobs.filter(x=>stateGroup(x)==='completed').length,failed:jobs.filter(x=>stateGroup(x)==='failed').length,files:jobs.reduce((sum,x)=>sum+(x.files?.length||0),0)}},[data.jobs])
 const sortedJobs=[...(data.jobs||[])].filter(x=>filter==='all'||stateGroup(x)===filter).filter(x=>{const q=query.trim().toLowerCase();if(!q)return true;return [x.order_number,x.files?.[0]?.original_name,x.id,x.processor_name].filter(Boolean).some(v=>String(v).toLowerCase().includes(q))}).sort((a,b)=>{const av=new Date(a.updated_at||a.created_at||0).getTime(),bv=new Date(b.updated_at||b.created_at||0).getTime();if(sort==='oldest')return av-bv;if(sort==='status')return String(a.status||'').localeCompare(String(b.status||''));return bv-av})
 const completedIds=(data.jobs||[]).filter(x=>['completed','partial_completed'].includes(x.status)||['completed','partial_completed'].includes(x.job?.state)).map(x=>x.id)
 if(!authToken)return <main className="processing-page"><section className="processing-auth"><Workflow/><h1>{isZh?'请先登录':'Sign in required'}</h1><button onClick={()=>setPage('login')}>{isZh?'前往登录':'Sign in'}</button></section></main>
 return <div className="enterprise-page-layout live-tasks-layout"><EnterpriseSidebar setPage={setPage} active="processing"/><main className="processing-page enterprise-page-content"><section className="processing-shell"><div className="processing-title"><div><span>V{VERSION} · LIVE PROCESSING ENGINE</span><h1>{isZh?'真实处理中心':'Live Processing Center'}</h1><p>{isZh?'管理正在处理、已完成和失败任务；支持下载、重试与安全删除。':'Manage active, completed and failed jobs with download, retry and secure deletion.'}</p></div><button className="refresh-live" onClick={load}><RefreshCw/>{isZh?'刷新状态':'Refresh'}</button></div><section className="processing-metrics"><article><span>{isZh?'任务总数':'Total jobs'}</span><b>{liveSummary.total}</b></article><article><span>{isZh?'正在处理':'Active'}</span><b>{liveSummary.active}</b></article><article><span>{isZh?'已完成':'Completed'}</span><b>{liveSummary.completed}</b></article><article><span>{isZh?'失败':'Failed'}</span><b>{liveSummary.failed}</b></article><article><span>{isZh?'文件总数':'Files'}</span><b>{liveSummary.files}</b></article></section><div className="processing-toolbar"><div className="processing-tabs">{[['active',isZh?'处理中':'Active'],['completed',isZh?'已完成':'Completed'],['failed',isZh?'失败':'Failed'],['all',isZh?'全部':'All']].map(([v,l])=><button className={filter===v?'active':''} onClick={()=>setFilter(v)} key={v}>{l}</button>)}</div><div className="processing-toolbar-actions"><label className="processing-search-v348"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={isZh?'搜索文件名、订单号或任务 ID':'Search file, order or task ID'}/></label><select value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">{isZh?'最新优先':'Newest'}</option><option value="oldest">{isZh?'最旧优先':'Oldest'}</option><option value="status">{isZh?'按状态':'Status'}</option></select><button onClick={()=>setChecked(checked.length===sortedJobs.length?[]:sortedJobs.map(x=>x.id))}><CheckSquare/>{checked.length===sortedJobs.length&&sortedJobs.length?(isZh?'取消全选':'Clear'):(isZh?'全选':'Select all')}</button>{completedIds.length>0&&<button className="danger-outline" onClick={()=>setConfirm({ids:completedIds,operation:'delete',permanent:true,title:isZh?`${completedIds.length} 个已完成任务`:`${completedIds.length} completed jobs`})}><Trash2/>{isZh?'清空已完成':'Clear completed'}</button>}</div></div>{checked.length>0&&<div className="bulk-bar"><b>{checked.length} {isZh?'项已选择':'selected'}</b><button className="danger-outline" onClick={()=>setConfirm({ids:checked,operation:'delete',permanent:true,title:isZh?`${checked.length} 个任务`:`${checked.length} jobs`})}><Trash2/>{isZh?'删除':'Delete'}</button></div>}{error&&<div className="processing-error">{error}</div>}<section className="live-job-list">{sortedJobs.map(item=>{const job=item.job||{},complete=['completed','partial_completed'].includes(item.status)||['completed','partial_completed'].includes(job.state),failed=item.status==='failed'||job.state==='failed',cancelled=item.status==='cancelled'||job.state==='cancelled',paused=job.state==='paused',open=expanded===item.id;return <article className={`live-job-card ${complete?'complete':''} ${failed?'failed':''}`} key={item.id}><header><button className="job-check" onClick={()=>setChecked(v=>v.includes(item.id)?v.filter(x=>x!==item.id):[...v,item.id])}>{checked.includes(item.id)?<CheckSquare/>:<Square/>}</button><button className="job-main" onClick={()=>setExpanded(open?null:item.id)}><div className="job-file-summary"><FileText/><div><b>{item.files?.[0]?.original_name||item.order_number}</b><small>{item.order_number} · {item.files?.length||0} {isZh?'个文件':'files'}</small></div></div>{complete?<div className="completed-summary"><CircleCheck/><div><b>{isZh?'处理完成':'Completed'}</b><small>{item.completed_at?`${isZh?'完成于':'Completed'} ${new Date(item.completed_at).toLocaleString()}`:(isZh?'交付文件已生成':'Delivery is ready')}</small></div></div>:<div className="job-live-progress"><div><i><em style={{width:`${failed?Math.min(Number(job.progress||0),95):Number(job.progress||0)}%`}}/></i><b>{failed?'—':`${job.progress||0}%`}</b></div><span className={`live-state ${failed?'failed':'active'}`}>{statusText(job.state||item.status)}</span></div>}</button><div className="job-actions">{!complete&&!failed&&!cancelled&&job.id&&<>{paused?<button title={isZh?'继续处理':'Resume'} onClick={()=>controlJob(job.id,'resume')}><Play/></button>:<button title={isZh?'暂停处理':'Pause'} onClick={()=>controlJob(job.id,'pause')}><Pause/></button>}<button className="stop-job-button" title={isZh?'停止处理':'Stop'} onClick={()=>{if(window.confirm(isZh?'确定停止当前任务？当前 AI 请求完成后将安全停止。':'Stop this job after the current AI request finishes?'))controlJob(job.id,'stop')}}><Octagon/></button></>}{(complete||failed||cancelled)&&<button title={isZh?'重新处理':'Retry'} onClick={()=>setConfirm({ids:[item.id],operation:'retry',title:item.files?.[0]?.original_name||item.order_number})}><RotateCcw/></button>}<button title={isZh?'永久删除':'Delete permanently'} onClick={()=>setConfirm({ids:[item.id],operation:'delete',permanent:true,title:item.files?.[0]?.original_name||item.order_number})}><Trash2/></button></div></header>{!complete&&<div className="current-stage"><span>{cancelled?(isZh?'停止状态':'Stop status'):failed?(isZh?'失败原因':'Failure reason'):(isZh?'当前阶段':'Current stage')}</span><b>{cancelled?(isZh?'任务已安全停止，可重新处理':'Job stopped safely; it can be retried'):failed?(job.error_message||item.error_message||job.message||(isZh?'任务被中断，请展开查看详情或重新处理':'The task was interrupted; open details or retry')):stepText(job.current_step)}</b>{job.estimated_remaining_seconds>0&&<small>{isZh?`预计剩余 ${job.estimated_remaining_seconds} 秒`:`ETA ${job.estimated_remaining_seconds}s`}</small>}</div>}{open&&<div className="job-detail"><div className="job-facts"><span><Clock3/><b>{isZh?'开始时间':'Started'}</b><small>{item.started_at?new Date(item.started_at).toLocaleString():(isZh?'尚未开始':'Not started')}</small></span><span><CircleCheck/><b>{isZh?'完成时间':'Completed'}</b><small>{item.completed_at?new Date(item.completed_at).toLocaleString():(complete?(isZh?'完成时间未记录':'Completion time unavailable'):(isZh?'尚未完成':'Not completed'))}</small></span><span><Clock3/><b>{isZh?'总耗时':'Duration'}</b><small>{item.duration_seconds!=null?`${Math.floor(item.duration_seconds/60)}m ${item.duration_seconds%60}s`:(isZh?'处理中':'In progress')}</small></span><span><Sparkles/><b>{isZh?'AI 点数':'AI credits'}</b><small>{Number(item.credits_used||0).toLocaleString()}</small></span><span><ShieldCheck/><b>{isZh?'处理人':'Processor'}</b><small>{item.processor_name||(isZh?'系统自动处理':'System automation')}</small></span><span><Cpu/><b>{isZh?'AI 服务':'AI provider'}</b><small>{item.ai_provider|| (isZh?'未使用 AI 翻译':'No AI translation')}</small></span><span><Bot/><b>{isZh?'模型':'Model'}</b><small>{item.ai_model|| (isZh?'未配置':'Not configured')}</small></span></div><div className="pipeline-steps">{(job.steps||[]).map(step=><div className={`pipeline-step ${step.status}`} key={step.step_key}><span>{step.status==='completed'?<CircleCheck/>:step.status==='failed'?<X/>:<i/>}</span><div><b>{stepText(step.step_key)}</b><small>{step.message||statusText(step.status)}</small></div><em>{step.status==='running'?`${step.progress||0}%`:step.status==='completed'?'✓':'—'}</em></div>)}</div>{item.output_files?.length>0&&<div className="delivery-actions">{item.output_files.map(f=>{const ext=(f.original_name.split('.').pop()||'FILE').toUpperCase();return <a key={f.id} href={`${API_BASE}${f.download_url}`} title={f.original_name}><Download/><span>{isZh?'下载':'Download'} {ext}</span><small>{f.original_name}</small></a>})}</div>}{(failed||cancelled)&&<button className="retry-job" onClick={()=>setConfirm({ids:[item.id],operation:'retry',title:item.files?.[0]?.original_name||item.order_number})}><RotateCcw/>{isZh?'重新处理':'Retry'}</button>}</div>}</article>})}</section>{!loading&&!sortedJobs.length&&<div className="processing-empty"><FileText/><h2>{isZh?'当前分类暂无任务':'No jobs in this view'}</h2></div>}{confirm&&<ConfirmDialog {...{confirm,setConfirm,action:taskAction,isZh}}/>}</section></main></div>
}

function Dashboard({t,setPage,authToken,currentUser}){
 const [orders,setOrders]=useState([]),[total,setTotal]=useState(0),[loading,setLoading]=useState(true),[error,setError]=useState('')
 const isZh=document.documentElement.lang.startsWith('zh')
 const copy=isZh?{
  greeting:`早上好，${currentUser?.name||currentUser?.email||'用户'} 👋`,sub:'欢迎回到 Document Automation AI 企业工作台',newTask:'新建处理任务',all:'全部任务',processing:'正在处理',completed:'已完成',credits:'账户额度',recent:'最近任务',live:'实时处理中心',docs:'最近文档',providers:'AI 服务商状态',knowledge:'企业知识库概览',viewAll:'查看全部',noData:'暂无真实数据',retry:'重试',failed:'加载失败',status:'状态',progress:'进度',language:'语言',updated:'更新时间',action:'操作',open:'查看',download:'下载',waiting:'等待中',active:'处理中',done:'已完成',failedState:'失败',plan:'当前套餐',members:'成员数量',expires:'到期时间',signout:'退出登录',nav:['首页','企业工作台','文档处理','实时任务','文档中心','企业知识库','AI 服务商','模板中心','团队与权限','套餐与额度','系统设置']
 }:{
  greeting:`Good morning, ${currentUser?.name||currentUser?.email||'User'} 👋`,sub:'Welcome back to the Document Automation AI Enterprise Workspace',newTask:'New processing task',all:'All tasks',processing:'Processing',completed:'Completed',credits:'Account credits',recent:'Recent tasks',live:'Live processing center',docs:'Recent documents',providers:'AI provider status',knowledge:'Enterprise knowledge overview',viewAll:'View all',noData:'No real data yet',retry:'Retry',failed:'Unable to load',status:'Status',progress:'Progress',language:'Language',updated:'Updated',action:'Action',open:'Open',download:'Download',waiting:'Waiting',active:'Processing',done:'Completed',failedState:'Failed',plan:'Current plan',members:'Members',expires:'Expires',signout:'Sign out',nav:['Home','Enterprise Workspace','Document Processing','Live Tasks','Document Center','Enterprise Knowledge','AI Providers','Template Center','Team & Permissions','Plans & Credits','System Settings']
 }
 const normalize=value=>(Array.isArray(value)?value:[]).filter(x=>x&&typeof x==='object').map((x,i)=>({
  id:x.id||x.order_number||i,order_number:String(x.order_number||`ORDER-${i+1}`),file_name:String(x.file_name||x.files?.[0]?.original_name||x.order_number||`Document ${i+1}`),services:Array.isArray(x.services)?x.services:[],status:String(x.status||x.job?.state||'processing').toLowerCase(),progress:Math.min(100,Math.max(0,Number(x.progress||x.job?.overall_progress||0))),created_at:x.updated_at||x.created_at||null,output_files:Array.isArray(x.output_files)?x.output_files:[]
 }))
 const load=async()=>{setLoading(true);setError('');try{const r=await fetch(`${API_BASE}/api/dashboard/recent-orders`,{headers:authToken?{Authorization:`Bearer ${authToken}`}:{}});if(!r.ok)throw new Error(String(r.status));const d=await r.json();const rows=normalize(d?.orders);setOrders(rows);setTotal(Number.isFinite(Number(d?.total))?Number(d.total):rows.length)}catch(e){console.error(e);setOrders([]);setTotal(0);setError(copy.failed)}finally{setLoading(false)}}
 useEffect(()=>{load()},[authToken])
 const kind=o=>o.status.includes('fail')?'failed':o.status.includes('complete')?'done':o.status.includes('queue')||o.status.includes('wait')?'waiting':'processing'
 const completed=orders.filter(o=>kind(o)==='done'),active=orders.filter(o=>kind(o)==='processing'||kind(o)==='waiting'),failed=orders.filter(o=>kind(o)==='failed'),live=active[0]
 const statusText=k=>({done:copy.done,processing:copy.active,waiting:copy.waiting,failed:copy.failedState}[k]||copy.active)
 const steps=['Document Parsing','OCR Recognition','AI Translation','Layout Reconstruction','Quality Validation','Export Delivery']
 const navActions=[()=>setPage('home'),()=>{},()=>setPage('order'),()=>setPage('processing'),()=>setPage('projects'),()=>setPage('knowledge'),()=>setPage('aiProviders'),()=>setPage('templates'),()=>setPage('team'),()=>setPage('billing'),()=>setPage('settings')]
 return <main className="enterprise-workspace-v33">
  <aside className="ew-sidebar"><button className="ew-brand ew-brand-button" onClick={()=>setPage('home')} title={isZh?'返回首页':'Back to home'}><span>DA</span><div><b>Document Automation AI</b><small>{isZh?'企业文档智能平台':'Enterprise Document Intelligence'}</small></div></button><nav>{copy.nav.map((n,i)=><button key={n} className={i===1?'active':''} onClick={navActions[i]}>{[<House/>,<LayoutDashboard/>,<FileText/>,<Clock3/>,<FolderOpen/>,<BookOpen/>,<Cpu/>,<Grid3X3/>,<ShieldCheck/>,<Sparkles/>,<Workflow/>][i]}<span>{n}</span></button>)}</nav><section className="ew-account"><div><span>{(currentUser?.name||currentUser?.email||'U').slice(0,1).toUpperCase()}</span><p><b>{currentUser?.name||currentUser?.email||'User'}</b><small>{currentUser?.email||''}</small></p></div><dl><dt>{copy.plan}</dt><dd>—</dd><dt>{copy.members}</dt><dd>—</dd><dt>{copy.expires}</dt><dd>—</dd></dl><button onClick={()=>setPage('home')}><ArrowLeft/>{copy.signout}</button></section></aside>
  <section className="ew-content"><header className="ew-top"><div><h1>{copy.greeting}</h1><p>{copy.sub}</p></div><div><button className="ew-primary" onClick={()=>setPage('order')}><Sparkles/>{copy.newTask}</button><button className="ew-icon"><Languages/></button><button className="ew-avatar">{(currentUser?.name||currentUser?.email||'U').slice(0,1).toUpperCase()}</button></div></header>
  {error&&<div className="ew-error"><AlertTriangle/><span>{error}</span><button onClick={load}>{copy.retry}</button></div>}
  <section className="ew-metrics">{[
   [copy.all,total,`${orders.length} ${isZh?'条已加载':'loaded'}`,FileText,'blue'],[copy.processing,active.length,`${failed.length} ${isZh?'个失败':'failed'}`,RefreshCw,'green'],[copy.completed,completed.length,total?`${Math.round(completed.length/Math.max(1,total)*100)}%`: '—',CircleCheck,'purple'],[copy.credits,'—',isZh?'等待账户接口':'Awaiting account API',Sparkles,'orange']
  ].map(([label,value,note,Icon,color])=><article key={label}><span className={color}><Icon/></span><div><small>{label}</small><b>{value}</b><em>{note}</em></div></article>)}</section>
  <section className="ew-grid ew-main-grid"><article className="ew-card ew-recent"><header><div><h2>{copy.recent}</h2><p>{isZh?'显示数据库中的真实处理记录':'Showing real processing records from the database'}</p></div><button onClick={()=>setPage('projects')}>{copy.viewAll}</button></header>{loading?<div className="ew-skeleton">Loading…</div>:orders.length?<div className="ew-table"><div className="ew-tr ew-th"><span>{isZh?'文件名称':'File'}</span><span>{isZh?'处理能力':'Capability'}</span><span>{copy.progress}</span><span>{copy.status}</span><span>{copy.updated}</span><span>{copy.action}</span></div>{orders.slice(0,6).map(o=>{const k=kind(o);return <div className="ew-tr" key={o.id}><span className="ew-file"><FileText/><b title={o.file_name}>{o.file_name}</b></span><span>{o.services.length?o.services.join(' · '):'—'}</span><span className="ew-progress"><i><em style={{width:`${o.progress}%`}}/></i><b>{o.progress}%</b></span><span><i className={`ew-status ${k}`}>{statusText(k)}</i></span><span>{o.created_at?new Date(o.created_at).toLocaleString():'—'}</span><span><button onClick={()=>setPage('processing')}><Eye/></button>{k==='done'&&<button><Download/></button>}</span></div>})}</div>:<div className="ew-empty"><FileText/><b>{copy.noData}</b><button onClick={()=>setPage('order')}>{copy.newTask}</button></div>}</article>
  <article className="ew-card ew-live"><header><div><h2>{copy.live}</h2><p>{isZh?'当前活动任务的实时状态':'Real-time status of the current active job'}</p></div><button onClick={()=>setPage('processing')}>{copy.viewAll}</button></header>{live?<><div className="ew-live-file"><FileText/><div><b>{live.file_name}</b><small>{live.order_number}</small></div><strong>{live.progress}%</strong></div><div className="ew-live-bar"><i style={{width:`${live.progress}%`}}/></div><ol>{steps.map((s,i)=>{const threshold=(i+1)*16.7;const done=live.progress>=threshold,run=!done&&live.progress>=i*16.7;return <li className={done?'done':run?'run':''} key={s}><span>{done?<Check/>:i+1}</span><b>{s}</b><small>{done?copy.done:run?copy.active:copy.waiting}</small></li>})}</ol></>:<div className="ew-empty compact"><Workflow/><b>{isZh?'当前没有正在处理的任务':'No active processing task'}</b></div>}</article></section>
  <section className="ew-grid ew-bottom-grid"><article className="ew-card"><header><h2>{copy.docs}</h2><button onClick={()=>setPage('projects')}>{copy.viewAll}</button></header><div className="ew-list">{orders.slice(0,5).map(o=><div key={o.id}><FileText/><span><b>{o.file_name}</b><small>{o.created_at?new Date(o.created_at).toLocaleString():'—'}</small></span><i className={`ew-status ${kind(o)}`}>{statusText(kind(o))}</i></div>)}{!orders.length&&<div className="ew-empty compact">{copy.noData}</div>}</div></article><article className="ew-card"><header><h2>{copy.providers}</h2><button onClick={()=>setPage('aiProviders')}>{copy.viewAll}</button></header><div className="ew-list muted">{['OpenAI','Google Gemini','Anthropic Claude','Azure OpenAI','Local Model'].map(n=><div key={n}><Cpu/><span><b>{n}</b><small>{isZh?'状态由服务商中心提供':'Status provided by AI Services'}</small></span><i>—</i></div>)}</div></article><article className="ew-card"><header><h2>{copy.knowledge}</h2><button onClick={()=>setPage('knowledge')}>{copy.viewAll}</button></header><div className="ew-list muted">{[[isZh?'企业术语库':'Enterprise Terminology',BookOpen],[isZh?'行业知识库':'Industry Knowledge',BrainCircuit],[isZh?'翻译记忆库':'Translation Memory',Languages],[isZh?'文档模板':'Document Templates',Grid3X3]].map(([n,I])=><div key={n}><I/><span><b>{n}</b><small>{isZh?'等待知识库统计接口':'Awaiting knowledge statistics API'}</small></span><i>—</i></div>)}</div></article></section>
  </section></main>
}



function BackupCenter({locale,setPage,authToken}){
 const zh=(locale||'').startsWith('zh'),[data,setData]=useState({backups:[],policy:{enabled:true,frequency:'daily',retention:14}}),[loading,setLoading]=useState(true),[busy,setBusy]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[note,setNote]=useState('')
 const headers={Authorization:`Bearer ${authToken}`,'Content-Type':'application/json'}
 const load=async()=>{setLoading(true);setError('');try{const r=await fetch(`${API_BASE}/api/admin/backups`,{headers:{Authorization:`Bearer ${authToken}`}});const j=await readJson(r);if(!r.ok)throw new Error(j.detail||'Backup service unavailable');setData(j)}catch(e){setError(e.message)}finally{setLoading(false)}}
 useEffect(()=>{load()},[authToken])
 const create=async()=>{setBusy('create');setError('');setNotice('');try{const r=await fetch(`${API_BASE}/api/admin/backups`,{method:'POST',headers,body:JSON.stringify({note})});const j=await readJson(r);if(!r.ok)throw new Error(j.detail||'Create failed');setNote('');setNotice(zh?'备份创建成功。':'Backup created successfully.');await load()}catch(e){setError(e.message)}finally{setBusy('')}}
 const savePolicy=async policy=>{setBusy('policy');setError('');try{const r=await fetch(`${API_BASE}/api/admin/backups/policy`,{method:'PUT',headers,body:JSON.stringify(policy)});const j=await readJson(r);if(!r.ok)throw new Error(j.detail||'Save failed');setData(v=>({...v,policy:j}));setNotice(zh?'自动备份策略已保存。':'Automatic backup policy saved.')}catch(e){setError(e.message)}finally{setBusy('')}}
 const remove=async item=>{if(!window.confirm(zh?`确定删除备份 ${item.id}？此操作不可恢复。`:`Delete backup ${item.id}? This cannot be undone.`))return;setBusy(item.id);try{const r=await fetch(`${API_BASE}/api/admin/backups/${item.id}`,{method:'DELETE',headers:{Authorization:`Bearer ${authToken}`}});const j=await readJson(r);if(!r.ok)throw new Error(j.detail||'Delete failed');await load()}catch(e){setError(e.message)}finally{setBusy('')}}
 const restore=async item=>{const ok=window.confirm(zh?'恢复会覆盖当前数据库和平台配置。系统会先自动创建安全备份。确定继续吗？':'Restore will replace the current database and platform configuration. A safety backup will be created first. Continue?');if(!ok)return;const typed=window.prompt(zh?'请输入 RESTORE 确认恢复：':'Type RESTORE to confirm:','');if(typed!=='RESTORE')return;setBusy(item.id);setError('');setNotice('');try{const r=await fetch(`${API_BASE}/api/admin/backups/${item.id}/restore`,{method:'POST',headers,body:JSON.stringify({confirmation:'RESTORE'})});const j=await readJson(r);if(!r.ok)throw new Error(j.detail||'Restore failed');setNotice(zh?'恢复完成。系统已在恢复前创建安全备份，建议重新启动后端。':'Restore completed. A safety backup was created first. Restarting the backend is recommended.');await load()}catch(e){setError(e.message)}finally{setBusy('')}}
 const policy=data.policy||{enabled:true,frequency:'daily',retention:14}
 const typeLabel=t=>({manual:zh?'手动备份':'Manual',automatic:zh?'自动备份':'Automatic',pre_restore:zh?'恢复前安全备份':'Pre-restore safety'}[t]||t)
 return <div className="enterprise-page-layout backup-shell"><style>{`
  .backup-shell{min-height:100vh;background:#f5f7fb;display:grid;grid-template-columns:248px minmax(0,1fr)}.backup-shell .unified-enterprise-sidebar{width:248px;min-width:248px;position:sticky;top:0;height:100vh}.backup-main{min-width:0;padding:30px 34px 50px}.backup-wrap{max-width:1450px;margin:0 auto}.backup-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:22px}.backup-head span{font-size:12px;font-weight:800;letter-spacing:1.1px;color:#5265e8}.backup-head h1{margin:7px 0 7px;font-size:30px}.backup-head p{margin:0;color:#667085}.backup-refresh{display:flex;gap:8px;align-items:center;padding:10px 14px;background:#fff;border:1px solid #d7dce5;border-radius:11px}.backup-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(320px,.7fr);gap:18px;margin-bottom:18px}.backup-card{background:#fff;border:1px solid #e4e8ef;border-radius:16px;padding:20px;box-shadow:0 4px 14px rgba(16,24,40,.03)}.backup-card h2{margin:0 0 8px;font-size:18px}.backup-card>p{margin:0 0 18px;color:#667085}.backup-create-row{display:flex;gap:10px}.backup-create-row input{flex:1;border:1px solid #d7dce5;border-radius:10px;padding:11px 12px}.backup-primary{display:flex;gap:8px;align-items:center;border:0;border-radius:10px;padding:11px 15px;background:#5665e8;color:#fff;font-weight:700}.backup-policy-row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.backup-policy-row label{font-size:13px;color:#475467}.backup-policy-row select,.backup-policy-row input{display:block;width:100%;margin-top:7px;padding:10px;border:1px solid #d7dce5;border-radius:9px}.backup-toggle{display:flex;justify-content:space-between;align-items:center;padding:12px;background:#f8f9fc;border-radius:10px}.backup-toggle input{width:18px;height:18px}.backup-save{margin-top:14px;width:100%;justify-content:center}.backup-message{padding:12px 14px;border-radius:10px;margin-bottom:16px}.backup-message.error{background:#fff1f0;color:#b42318}.backup-message.ok{background:#ecfdf3;color:#067647}.backup-list-card{padding:0;overflow:hidden}.backup-list-head{display:flex;justify-content:space-between;align-items:center;padding:20px;border-bottom:1px solid #eaecf0}.backup-list-head h2{margin:0}.backup-table{width:100%;border-collapse:collapse}.backup-table th,.backup-table td{text-align:left;padding:14px 18px;border-bottom:1px solid #f0f2f5;font-size:13px}.backup-table th{color:#667085;background:#fafbfc;font-weight:600}.backup-id{display:flex;gap:10px;align-items:center}.backup-id svg{color:#5265e8}.backup-id b{display:block}.backup-id small{color:#667085}.backup-tag{display:inline-flex;padding:4px 8px;border-radius:999px;background:#eef1ff;color:#4353c7;font-weight:700}.backup-actions{display:flex;gap:7px}.backup-actions button,.backup-actions a{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border:1px solid #dfe3ea;border-radius:9px;background:#fff;color:#344054}.backup-actions .restore{width:auto;padding:0 10px}.backup-actions .delete{color:#b42318}.backup-empty{text-align:center;padding:48px;color:#667085}.backup-empty svg{display:block;margin:0 auto 10px}.backup-security{display:flex;gap:12px;align-items:flex-start;padding:15px;background:#f8f9ff;border:1px solid #e5e8ff;border-radius:12px;margin-top:18px;color:#475467}.backup-security svg{flex:0 0 auto;color:#5265e8}@media(max-width:1000px){.backup-shell{grid-template-columns:210px minmax(0,1fr)}.backup-shell .unified-enterprise-sidebar{width:210px;min-width:210px}.backup-grid{grid-template-columns:1fr}.backup-main{padding:24px 20px}}@media(max-width:760px){.backup-shell{display:block}.backup-shell .unified-enterprise-sidebar{position:relative;width:100%;height:auto}.backup-main{padding:20px 14px}.backup-head{flex-direction:column}.backup-create-row{flex-direction:column}.backup-table{min-width:850px}.backup-list-card{overflow:auto}}
 `}</style><EnterpriseSidebar setPage={setPage} active="backups" platformAdmin/><main className="backup-main"><section className="backup-wrap"><header className="backup-head"><div><span>V43 · PLATFORM ADMIN</span><h1>{zh?'数据备份与恢复中心':'Backup & Restore Center'}</h1><p>{zh?'保护平台数据库、企业知识库和关键配置；普通客户无法访问。':'Protect the platform database, enterprise knowledge and critical configuration. Customer accounts cannot access this page.'}</p></div><button className="backup-refresh" onClick={load}><RefreshCw size={17}/>{zh?'刷新':'Refresh'}</button></header>{error&&<div className="backup-message error"><AlertTriangle size={15}/> {error}</div>}{notice&&<div className="backup-message ok"><CircleCheck size={15}/> {notice}</div>}<section className="backup-grid"><article className="backup-card"><h2>{zh?'立即创建备份':'Create a backup now'}</h2><p>{zh?'使用 SQLite 安全快照，不中断当前文档处理任务。':'Uses a safe SQLite snapshot without interrupting document processing.'}</p><div className="backup-create-row"><input value={note} onChange={e=>setNote(e.target.value)} maxLength={500} placeholder={zh?'备份说明（可选）':'Backup note (optional)'}/><button className="backup-primary" onClick={create} disabled={!!busy}><Save size={17}/>{busy==='create'?(zh?'正在备份…':'Creating…'):(zh?'创建备份':'Create backup')}</button></div><div className="backup-security"><ShieldCheck/><span>{zh?'备份包含数据库、数据目录中的配置，以及企业知识库相关文件；不会把运行环境和 node_modules 打入备份。':'Backups include the database, configuration stored in the data directory, and enterprise knowledge files. Runtime environments and node_modules are excluded.'}</span></div></article><article className="backup-card"><h2>{zh?'自动备份策略':'Automatic backup policy'}</h2><div className="backup-toggle"><span>{zh?'启用自动备份':'Enable automatic backups'}</span><input type="checkbox" checked={!!policy.enabled} onChange={e=>setData(v=>({...v,policy:{...policy,enabled:e.target.checked}}))}/></div><div className="backup-policy-row"><label>{zh?'执行频率':'Frequency'}<select value={policy.frequency} onChange={e=>setData(v=>({...v,policy:{...policy,frequency:e.target.value}}))}><option value="daily">{zh?'每天':'Daily'}</option><option value="weekly">{zh?'每周':'Weekly'}</option></select></label><label>{zh?'保留自动备份数量':'Automatic backups to keep'}<input type="number" min="1" max="90" value={policy.retention} onChange={e=>setData(v=>({...v,policy:{...policy,retention:Number(e.target.value)}}))}/></label></div><button className="backup-primary backup-save" disabled={!!busy} onClick={()=>savePolicy(policy)}><Save size={16}/>{busy==='policy'?(zh?'保存中…':'Saving…'):(zh?'保存策略':'Save policy')}</button></article></section><article className="backup-card backup-list-card"><header className="backup-list-head"><h2>{zh?'备份历史':'Backup history'}</h2><span>{data.backups?.length||0} {zh?'个版本':'versions'}</span></header>{loading?<div className="backup-empty">{zh?'正在读取备份…':'Loading backups…'}</div>:data.backups?.length?<table className="backup-table"><thead><tr><th>{zh?'备份':'Backup'}</th><th>{zh?'类型':'Type'}</th><th>{zh?'创建时间':'Created'}</th><th>{zh?'大小':'Size'}</th><th>{zh?'创建者':'Created by'}</th><th>{zh?'操作':'Actions'}</th></tr></thead><tbody>{data.backups.map(item=><tr key={item.id}><td><div className="backup-id"><Database size={20}/><span><b>{item.id}</b><small>{item.note|| (zh?'无备注':'No note')}</small></span></div></td><td><span className="backup-tag">{typeLabel(item.type)}</span></td><td>{item.created_at?new Date(item.created_at).toLocaleString():'—'}</td><td>{item.size_display||'—'}</td><td>{item.created_by||'system'}</td><td><div className="backup-actions"><a title={zh?'下载':'Download'} href={`${API_BASE}/api/admin/backups/${item.id}/download`} onClick={e=>{e.preventDefault();fetch(`${API_BASE}/api/admin/backups/${item.id}/download`,{headers:{Authorization:`Bearer ${authToken}`}}).then(async r=>{if(!r.ok)throw new Error((await readJson(r)).detail||'Download failed');const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=item.filename;a.click();URL.revokeObjectURL(url)}).catch(e=>setError(e.message))}}><Download size={16}/></a><button className="restore" disabled={!!busy} onClick={()=>restore(item)}><ArchiveRestore size={16}/>{zh?'恢复':'Restore'}</button><button className="delete" disabled={!!busy} title={zh?'删除':'Delete'} onClick={()=>remove(item)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table>:<div className="backup-empty"><Database size={30}/>{zh?'还没有备份，建议现在创建第一个备份。':'No backups yet. Create the first backup now.'}</div>}</article></section></main></div>
}

function MonitoringCenter({locale,setPage,authToken,currentUser}){
 const zh=locale==='zh', [data,setData]=useState(null), [error,setError]=useState(''), [loading,setLoading]=useState(true), [updated,setUpdated]=useState('')
 const load=async()=>{setLoading(true);setError('');try{const r=await fetch(`${API_BASE}/api/admin/monitoring`,{headers:{Authorization:`Bearer ${authToken}`}});const j=await readJson(r);if(!r.ok)throw new Error(j.detail||'Monitoring unavailable');setData(j);setUpdated(new Date().toLocaleTimeString())}catch(e){setError(e.message)}finally{setLoading(false)}}
 useEffect(()=>{load();const timer=setInterval(load,15000);return()=>clearInterval(timer)},[authToken])
 const m=data?.metrics||{}, services=data?.services||{}, trend=data?.trend||[], alerts=data?.alerts||[]
 const labels={online:zh?'在线用户':'Online users',todayDocs:zh?'今日文档':'Documents today',active:zh?'当前任务':'Active jobs',success:zh?'处理成功率':'Success rate',todayUsers:zh?'今日注册':'New users today',revenue:zh?'今日收入':'Revenue today'}
 const cards=[[labels.online,m.online_users??'—',UserRound],[labels.todayDocs,m.orders_today??'—',FileText],[labels.active,m.active_jobs??'—',Activity],[labels.success,m.success_rate!=null?`${m.success_rate}%`:'—',CircleCheck],[labels.todayUsers,m.users_today??'—',UserRound],[labels.revenue,`¥${Number(m.revenue_today||0).toLocaleString()}`,Coins]]
 const max=Math.max(1,...trend.map(x=>Number(x.orders||0)))
 const serviceNames={backend:zh?'后端服务':'Backend',database:zh?'数据库':'Database',storage:zh?'文件存储':'Storage',ai:zh?'AI 服务':'AI service',payments:zh?'支付服务':'Payments'}
 const localAlert=a=>{if(!zh)return a;const title=String(a?.title||'');const detail=String(a?.detail||'');if(/failed document jobs/i.test(title))return {title:'文档处理失败',detail:detail.replace(/(\d+) failed jobs require review\.?/i,'有 $1 个失败任务需要检查。')};return {title,detail}}
 return <div className="enterprise-page-layout monitoring-shell"><style>{`
  .monitoring-shell{min-height:100vh;background:#f4f7fb;display:grid;grid-template-columns:248px minmax(0,1fr);overflow-x:hidden}
  .monitoring-shell .unified-enterprise-sidebar{width:248px;min-width:248px;position:sticky;top:0;height:100vh;overflow-y:auto;border-right:1px solid #e7ebf2;background:#fff}
  .monitoring-main{min-width:0;background:#f4f7fb;min-height:100vh}
  .monitoring-wrap{padding:30px 34px 42px;max-width:1500px;margin:0 auto}
  .monitoring-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}
  .monitoring-kicker{font-size:12px;font-weight:800;color:#5265e8;letter-spacing:1.2px}
  .monitoring-head h1{margin:7px 0 6px;font-size:30px;line-height:1.2;color:#111827}
  .monitoring-head p{margin:0;color:#667085;font-size:15px}
  .monitoring-refresh{display:flex;align-items:center;gap:8px;padding:10px 14px;border:1px solid #d7dce5;border-radius:11px;background:#fff;cursor:pointer;white-space:nowrap;box-shadow:0 2px 8px rgba(16,24,40,.04)}
  .monitoring-refresh:hover{border-color:#9aa8ff;background:#f8f9ff}
  .monitoring-error{display:flex;align-items:center;gap:8px;padding:14px;border-radius:11px;background:#fff1f0;color:#b42318;margin-bottom:16px}
  .monitoring-cards{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px;margin-bottom:18px}
  .monitoring-card{min-width:0;background:#fff;border:1px solid #e4e8ef;border-radius:15px;padding:18px;box-shadow:0 4px 14px rgba(16,24,40,.035)}
  .monitoring-card svg{color:#344054}.monitoring-card small{display:block;color:#667085;margin:14px 0 6px}.monitoring-card b{font-size:25px;color:#101828}
  .monitoring-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(290px,.9fr);gap:18px;margin-bottom:18px}
  .monitoring-bottom{display:grid;grid-template-columns:1fr 1fr;gap:18px}
  .monitoring-panel{min-width:0;background:#fff;border:1px solid #e4e8ef;border-radius:15px;padding:20px;box-shadow:0 4px 14px rgba(16,24,40,.03)}
  .monitoring-panel h2{margin:0 0 16px;font-size:18px;color:#101828}
  .monitoring-chart{height:230px;display:flex;align-items:flex-end;gap:13px;padding-top:20px}
  .monitoring-bar{flex:1;min-width:0;text-align:center}.monitoring-bar>b{font-size:12px}.monitoring-bar i{display:block;background:linear-gradient(180deg,#5968ed,#aab3ff);border-radius:8px 8px 3px 3px;margin:7px auto;max-width:48px}.monitoring-bar small{color:#667085}
  .monitoring-row{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #f0f2f5;gap:16px}.monitoring-row:last-child{border-bottom:0}.monitoring-row b{font-size:13px}.monitoring-status-ok{color:#067647}.monitoring-status-warn{color:#b54708}.monitoring-status-error{color:#b42318}
  .monitoring-alert{padding:11px 0;border-bottom:1px solid #f2f4f7}.monitoring-alert:last-child{border-bottom:0}.monitoring-alert b{font-size:14px}.monitoring-alert small{display:block;color:#667085;margin-top:5px;line-height:1.5}
  .monitoring-empty{padding:30px 0;text-align:center;color:#667085}.monitoring-empty svg{display:block;margin:0 auto}.monitoring-empty p{margin-bottom:0}
  @media(max-width:1280px){.monitoring-cards{grid-template-columns:repeat(3,minmax(0,1fr))}}
  @media(max-width:980px){.monitoring-shell{grid-template-columns:210px minmax(0,1fr)}.monitoring-shell .unified-enterprise-sidebar{width:210px;min-width:210px}.monitoring-wrap{padding:24px 22px}.monitoring-grid,.monitoring-bottom{grid-template-columns:1fr}}
  @media(max-width:760px){.monitoring-shell{display:block}.monitoring-shell .unified-enterprise-sidebar{position:relative;width:100%;min-width:0;height:auto}.monitoring-head{flex-direction:column}.monitoring-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.monitoring-wrap{padding:20px 14px}.monitoring-chart{gap:8px}}
 `}</style><EnterpriseSidebar setPage={setPage} active="monitoring" platformAdmin/><main className="monitoring-main"><section className="monitoring-wrap">
  <header className="monitoring-head"><div><span className="monitoring-kicker">V42 · ADMIN ONLY</span><h1>{zh?'企业运营监控中心':'Operations Monitoring Center'}</h1><p>{zh?'仅平台管理员可见，客户账户不会显示此页面。':'Visible only to platform administrators; customer accounts cannot access this page.'}</p></div><button className="monitoring-refresh" onClick={load}><RefreshCw size={17}/>{loading?(zh?'刷新中':'Refreshing'):(zh?'刷新数据':'Refresh')} {updated&&<small>{updated}</small>}</button></header>
  {error&&<div className="monitoring-error"><AlertTriangle size={16}/> {error}</div>}
  <section className="monitoring-cards">{cards.map(([label,value,Icon])=><article className="monitoring-card" key={label}><Icon size={20}/><small>{label}</small><b>{loading?'…':value}</b></article>)}</section>
  <section className="monitoring-grid"><article className="monitoring-panel"><h2>{zh?'最近 7 天处理趋势':'7-day processing trend'}</h2><div className="monitoring-chart">{trend.map(x=><div className="monitoring-bar" key={x.date}><b>{x.orders}</b><i style={{height:`${Math.max(8,Number(x.orders||0)/max*170)}px`}}/><small>{x.date.slice(5)}</small></div>)}</div></article>
  <article className="monitoring-panel"><h2>{zh?'系统服务状态':'System services'}</h2>{Object.entries(services).map(([key,v])=>{const cls=v.status==='online'?'monitoring-status-ok':v.status==='error'?'monitoring-status-error':'monitoring-status-warn';return <div className="monitoring-row" key={key}><span>{serviceNames[key]||key}</span><b className={cls}>{v.status==='online'?(zh?'● 正常':'● Online'):v.status==='not_configured'?(zh?'● 未配置':'● Not configured'):(zh?'● 注意':'● Warning')}</b></div>})}</article></section>
  <section className="monitoring-bottom"><article className="monitoring-panel"><h2>{zh?'任务概览':'Job overview'}</h2>{[[zh?'全部任务':'All jobs',m.orders_total],[zh?'已完成':'Completed',m.completed_jobs],[zh?'处理中':'Active',m.active_jobs],[zh?'失败':'Failed',m.failed_jobs]].map(([k,v])=><div className="monitoring-row" key={k}><span>{k}</span><b>{v??'—'}</b></div>)}</article><article className="monitoring-panel"><h2>{zh?'最近告警':'Recent alerts'}</h2>{alerts.length?alerts.map((a,i)=>{const item=localAlert(a);return <div className="monitoring-alert" key={i}><b>{item.title}</b><small>{item.detail}</small></div>}):<div className="monitoring-empty"><ShieldCheck size={28}/><p>{zh?'当前没有系统告警':'No system alerts'}</p></div>}</article></section>
 </section></main></div>
}

export default App
